package com.singularity.todo.mcp
import com.singularity.todo.feature.ai.McpToolCatalog
import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.jsonObject
import org.junit.jupiter.api.Tag

/**
 * The committed tool surface must be the one the code declares.
 *
 * The file `config/docs/tool-surface.json` is generated by `:shared:exportToolSurface`
 * from the compiled classes, and the drift gate compares what it *parsed* out of the
 * Kotlin sources with what the compiler *saw*. This test is the other half of that
 * pair: it says the committed file is current, so a hand-edit of it is reported rather
 * than believed.
 *
 * The three facts line up like this:
 *
 * - the code declares the surface (the classes, the catalogue),
 * - the export is the code's surface, written down,
 * - the gate's parser is the export's surface, read back out of the sources.
 *
 * A parser that misreads a class breaks the third link, and the gate says so.
 */
@Tag("fast")
class ToolSurfaceExportTest {

    @Test
    fun `the committed tool surface is the one the code declares`() {
        val committed = File(repoRoot(), "config/docs/tool-surface.json")
        assertTrue(
            committed.isFile,
            "the tool surface has not been exported: ${committed.absolutePath} is missing — " +
                "run ./gradlew :shared:exportToolSurface",
        )

        val expected = ToolSurfaceExport.surface()
        // Parsed, not compared as text: the file is written pretty-printed, and the
        // question is whether it says the same thing — not whether it says it with the
        // same whitespace.
        val actual = Json.parseToJsonElement(committed.readText()).jsonObject

        assertEquals(
            expected,
            actual,
            "the committed tool surface differs from the one the code declares — " +
                "run ./gradlew :shared:exportToolSurface and commit the result",
        )
    }

    @Test
    fun `every declared tool is in the export`() {
        val exported = ToolSurfaceExport.surface()
        val tools = exported["tools"] as? JsonArray ?: error("the export has no tools")

        assertEquals(
            McpToolCatalog.catalog.size,
            tools.size,
            "the export must carry every catalogue entry — a tool that is declared but not " +
                "exported is a tool the gate cannot see",
        )
    }

    /**
     * The repository root, found by walking up from the working directory.
     *
     * The test runs with the module directory as its working directory, and the depth
     * is not something to hard-code: a path that is right today and wrong after a
     * directory is renamed is a failure nobody can explain.
     */
    private fun repoRoot(): File = generateSequence(File(System.getProperty("user.dir")).absoluteFile) {
        it.parentFile
    }
        .firstOrNull { File(it, "config/docs/adr-corpus.json").isFile }
        ?: error("could not find the repository root from ${System.getProperty("user.dir")}")
}
